  function animateNumber(el, value) {
    if (reduceMotion) { el.textContent = value.toLocaleString("ja-JP"); return; }
    var start = parseInt((el.textContent || "0").replace(/,/g, ""), 10) || 0;
    var duration = 600;
    var startTime = null;
    function step(ts) {
      if (startTime === null) startTime = ts;
      var progress = Math.min(1, (ts - startTime) / duration);
      var current = Math.floor(start + (value - start) * progress);
      el.textContent = current.toLocaleString("ja-JP");
      if (progress < 1) requestAnimationFrame(step);
      else el.textContent = value.toLocaleString("ja-JP");
    }
    requestAnimationFrame(step);
  }

  function setTab(tab) {
    state.tab = tab;
    ["home", "quests", "rewards", "history"].forEach(function (name) {
      var panel = $("panel-" + name);
      panel.hidden = name !== tab;
    });
    var current = $("panel-" + tab);
    current.classList.remove("tab-enter");
    void current.offsetWidth;
    current.classList.add("tab-enter");

    document.querySelectorAll(".nav-item").forEach(function (btn) {
      if (btn.dataset.tab === tab) btn.setAttribute("aria-current", "page");
      else btn.removeAttribute("aria-current");
    });

    if (tab === "history") renderHistory();
  }

  function renderQuests() {
    var list = $("quest-list");
    list.innerHTML = "";
    var quests = activeQuests();

    var top = quests.find(function (q) { return !q.completed; });
    if (top) {
      $("quick-desc").textContent = "「" + top.title.slice(0, 14) + (top.title.length > 14 ? "…" : "") + "」+" + top.reward.toLocaleString("ja-JP") + "pt";
    }

    quests.forEach(function (q) {
      var item = document.createElement("div");
      item.className = "list-item quest-item";

      var thumb = document.createElement("div");
      thumb.className = "list-thumb" + (q.isNew ? " alt" : "");
      if (q.char && CHAR_PHOTOS[q.char + "_chibi"]) {
        thumb.style.backgroundImage = "url('" + CHAR_PHOTOS[q.char + "_chibi"] + "')";
        thumb.classList.add("has-photo", "char-thumb");
      } else {
        thumb.innerHTML = ICONS[q.isNew ? "trophy" : "building"];
      }

      var info = document.createElement("div");
      info.className = "quest-info";

      var badgeRow = document.createElement("div");
      badgeRow.className = "quest-badges";
      var reward = document.createElement("span");
      reward.className = "quest-reward";
      reward.textContent = "+" + q.reward.toLocaleString("ja-JP") + " pt";
      badgeRow.appendChild(reward);
      if (q.isNew && !q.completed) {
        var nb = document.createElement("span");
        nb.className = "new-badge";
        nb.textContent = "NEW";
        badgeRow.appendChild(nb);
      }

      var title = document.createElement("p");
      title.className = "quest-title";
      title.textContent = q.title;
      info.appendChild(badgeRow);
      info.appendChild(title);

      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "quest-btn";
      if (q.completed) {
        btn.disabled = true;
        btn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/></svg> 達成済み';
      } else if (q.type === "survey") {
        btn.textContent = "回答する";
        btn.addEventListener("click", function () { openSurveyModal(q); });
      } else {
        btn.textContent = "クリアする";
        btn.addEventListener("click", function () { completeQuest(q.id, btn); });
      }

      item.appendChild(thumb);
      item.appendChild(info);
      item.appendChild(btn);
      list.appendChild(item);
    });
  }

  function grantQuestReward(q, originRect) {
    q.completed = true;
    state.points += q.reward;
    animateNumber($("card-points"), state.points);
    logHistory(q.title, "クエスト達成", q.reward);
    renderQuests();
    var cx = originRect ? originRect.left + originRect.width / 2 : window.innerWidth / 2;
    var cy = originRect ? originRect.top + originRect.height / 2 : window.innerHeight * 0.35;
    fireConfetti(cx, cy, THEMES[state.theme].confetti, 80);
  }

  function completeQuest(id, btn) {
    var q = activeQuests().find(function (x) { return x.id === id; });
    if (!q || q.completed) return;
    grantQuestReward(q, btn.getBoundingClientRect());
  }

  /* ---------- survey quest ---------- */
  var surveyState = { quest: null, answers: {} };

  function updateSurveySubmitState() {
    var answered = Object.keys(surveyState.answers).length;
    $("survey-submit").disabled = answered < SURVEY_QUESTIONS.length;
  }

  function renderSurveyQuestions() {
    var host = $("survey-questions");
    host.innerHTML = "";
    surveyState.answers = {};
    SURVEY_QUESTIONS.forEach(function (item, qi) {
      var wrap = document.createElement("div");
      wrap.className = "survey-q";

      var title = document.createElement("p");
      title.className = "survey-q-title";
      title.innerHTML = "<span>Q" + (qi + 1) + ".</span>" + item.q;

      var opts = document.createElement("div");
      opts.className = "survey-options";
      item.options.forEach(function (opt) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "survey-option";
        b.textContent = opt;
        b.setAttribute("aria-pressed", "false");
        b.addEventListener("click", function () {
          opts.querySelectorAll(".survey-option").forEach(function (o) { o.setAttribute("aria-pressed", "false"); });
          b.setAttribute("aria-pressed", "true");
          surveyState.answers[qi] = opt;
          updateSurveySubmitState();
        });
        opts.appendChild(b);
      });

      wrap.appendChild(title);
      wrap.appendChild(opts);
      host.appendChild(wrap);
    });
    updateSurveySubmitState();
  }

  function openSurveyModal(q) {
    surveyState.quest = q;
    renderSurveyQuestions();
    $("survey-step-form").hidden = false;
    $("survey-step-success").hidden = true;
    $("survey-modal").hidden = false;
  }

  function closeSurveyModal() {
    $("survey-modal").hidden = true;
  }

  function submitSurvey() {
    var q = surveyState.quest;
    if (!q || q.completed) { closeSurveyModal(); return; }
    grantQuestReward(q, null);
    $("survey-success-reward").textContent = "+" + q.reward.toLocaleString("ja-JP") + "pt 獲得しました";
    $("survey-step-form").hidden = true;
    $("survey-step-success").hidden = false;
  }

