  function applyBrandTile(el, r) {
    if (!r.brand || !BRAND_META[r.brand]) return false;
    var b = BRAND_META[r.brand];
    el.style.background = "linear-gradient(160deg, #f5f7fb, #e8ecf4)";

    var wrap = document.createElement("div");
    wrap.className = "brand-tile" + (b.wordmark ? " brand-tile-wordmark" : "");

    if (b.wordmark) {
      var rmark = document.createElement("span");
      rmark.className = "brand-r-mark";
      rmark.textContent = "R";
      var bar = document.createElement("span");
      bar.className = "brand-r-bar";
      wrap.appendChild(rmark);
      wrap.appendChild(bar);
    } else {
      var chip = document.createElement("div");
      chip.className = "point-chip";
      chip.style.background = b.chipBg;
      if (b.svg) {
        chip.innerHTML = b.svg;
      } else {
        var mark = document.createElement("span");
        mark.className = "point-chip-mark";
        mark.textContent = b.mark;
        chip.appendChild(mark);
      }
      wrap.appendChild(chip);
    }

    var label = document.createElement("span");
    label.className = "brand-label";
    label.textContent = b.label;
    wrap.appendChild(label);

    el.appendChild(wrap);
    return true;
  }

  function buildCouponCard(r, i, withButton) {
    var icons = ["mappin", "gift"];
    var card = document.createElement("div");
    card.className = "coupon-card";

    var media = document.createElement("div");
    media.className = "coupon-media" + (i % 2 === 1 ? " alt" : "");
    if (applyBrandTile(media, r)) {
      /* brand tile applied */
    } else if (r.photo && PHOTOS[r.photo]) {
      media.style.backgroundImage = "url('" + PHOTOS[r.photo] + "')";
      media.classList.add("has-photo");
    } else if (r.char && CHAR_PHOTOS[r.char + "_chibi"]) {
      media.style.backgroundImage = "url('" + CHAR_PHOTOS[r.char + "_chibi"] + "')";
      media.classList.add("has-photo", "char-media");
    } else {
      media.innerHTML = ICONS[icons[i % icons.length]];
    }

    var badge = document.createElement("span");
    badge.className = "coupon-media-badge";
    badge.textContent = r.type;
    media.appendChild(badge);

    if (r.isNew) {
      var nb = document.createElement("span");
      nb.className = "new-badge coupon-new";
      nb.textContent = "NEW";
      media.appendChild(nb);
    }

    var body = document.createElement("div");
    body.className = "coupon-body";
    var title = document.createElement("p");
    title.className = "coupon-title";
    title.textContent = r.title;
    var divider = document.createElement("div");
    divider.className = "coupon-divider";
    body.appendChild(title);
    body.appendChild(divider);

    if (withButton) {
      var detailLink = document.createElement("button");
      detailLink.type = "button";
      detailLink.className = "coupon-detail-link";
      detailLink.textContent = "詳しく見る ›";
      detailLink.addEventListener("click", function () { openRewardDetail(r); });
      body.appendChild(detailLink);

      var footer = document.createElement("div");
      footer.className = "coupon-footer";
      var cost = document.createElement("p");
      cost.className = "coupon-cost";
      cost.innerHTML = r.cost.toLocaleString("ja-JP") + "<span>pt</span>";
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "coupon-btn";
      btn.textContent = "交換する";
      btn.addEventListener("click", function () { openRewardConfirm(r); });
      footer.appendChild(cost);
      footer.appendChild(btn);
      body.appendChild(footer);
    } else {
      var cost2 = document.createElement("p");
      cost2.className = "coupon-cost";
      cost2.innerHTML = r.cost.toLocaleString("ja-JP") + "<span>pt</span>";
      body.appendChild(cost2);
    }

    card.appendChild(media);
    card.appendChild(body);
    return card;
  }

  function renderRewards() {
    var list = $("reward-list");
    list.innerHTML = "";

    var order = [];
    var groups = {};
    activeRewards().forEach(function (r) {
      if (!groups[r.type]) { groups[r.type] = []; order.push(r.type); }
      groups[r.type].push(r);
    });

    order.forEach(function (type) {
      var section = document.createElement("div");
      section.className = "reward-category";

      var title = document.createElement("h3");
      title.className = "reward-category-title";
      title.textContent = type;
      section.appendChild(title);

      var grid = document.createElement("div");
      grid.className = "reward-category-grid";
      groups[type].forEach(function (r, i) {
        grid.appendChild(buildCouponCard(r, i, true));
      });
      section.appendChild(grid);

      list.appendChild(section);
    });
  }

  /* ---------- reward redemption flow ---------- */
  var rewardFlow = { current: null };

  function rewardTerms(r) {
    return [
      "有効期限は交換から30日間です。",
      "交換したポイントは、再度ポイントに戻すことはできません。",
      "ポイントは有効期限が近いものから優先的に利用されます。",
      "在庫状況により、ご利用いただけない場合があります。"
    ];
  }

  function fillRewardMedia(el, r, iconFallback) {
    el.innerHTML = "";
    el.style.background = "";
    el.style.backgroundImage = "";
    el.style.color = "";
    el.classList.remove("has-photo");
    if (applyBrandTile(el, r)) {
      return;
    } else if (r.photo && PHOTOS[r.photo]) {
      el.style.backgroundImage = "url('" + PHOTOS[r.photo] + "')";
      el.classList.add("has-photo");
    } else if (r.char && CHAR_PHOTOS[r.char + "_chibi"]) {
      el.style.backgroundImage = "url('" + CHAR_PHOTOS[r.char + "_chibi"] + "')";
      el.classList.add("has-photo");
    } else {
      el.innerHTML = ICONS[iconFallback || "gift"];
    }
  }

  function openRewardDetail(r) {
    rewardFlow.current = r;
    fillRewardMedia($("rd-media"), r, "gift");
    var badgeHost = $("rd-media");
    var badge = document.createElement("span");
    badge.className = "rd-cost-badge";
    badge.id = "rd-cost-badge";
    badge.textContent = r.cost.toLocaleString("ja-JP") + " pt";
    badgeHost.appendChild(badge);

    $("rd-title").textContent = r.title;
    $("rd-desc").textContent = r.desc || "";

    var termsList = $("rd-terms");
    termsList.innerHTML = "";
    rewardTerms(r).forEach(function (t) {
      var li = document.createElement("li");
      li.textContent = t;
      termsList.appendChild(li);
    });

    var btn = $("rd-exchange-btn");
    var afford = state.points >= r.cost;
    btn.disabled = !afford;
    btn.textContent = afford ? "交換する" : "ポイントが不足しています";

    $("reward-detail").hidden = false;
  }

