  /* ---------- history ---------- */
  function logHistory(label, sub, delta) {
    state.history.unshift({ label: label, sub: sub, delta: delta, time: Date.now() });
  }

  function seedHistory() {
    function mk(label, sub, delta, daysAgo) {
      state.history.push({ label: label, sub: sub, delta: delta, time: Date.now() - daysAgo * 86400000 });
    }
    mk("デビットカード利用", "紀陽銀行 提携店舗", 150, 2);
    mk("口座振替ボーナス", "毎月の自動積立", 1000, 6);
    mk("アプリログインボーナス", "デイリーボーナス", 5, 9);
    mk("スタジアムチェックイン", "ホームゲーム来場", 500, 1);
    mk("ガチャを回す", "オリジナル応援ステッカーセット（N）が当選", -500, 3);
    mk("デビット決済利用", "地元提携店舗（老舗カフェ）", 300, 4);
    mk("チェックインボーナス", "わかおしっ！まちあるき", 80, 1);
    mk("缶バッジセット交換", "リワード交換", -2000, 3);
    mk("いつものランチで物語を発見しよう", "クエスト達成", 50, 5);
    state.history.sort(function (a, b) { return b.time - a.time; });
  }

  function formatHistoryDate(ts) {
    var diffDays = Math.floor((Date.now() - ts) / 86400000);
    if (diffDays <= 0) return "今日";
    if (diffDays === 1) return "昨日";
    if (diffDays < 7) return diffDays + "日前";
    var d = new Date(ts);
    return (d.getMonth() + 1) + "/" + d.getDate();
  }

  function renderHistory() {
    var all = state.history || [];
    var filtered = all.filter(function (h) {
      if (state.historyFilter === "earn") return h.delta > 0;
      if (state.historyFilter === "use") return h.delta < 0;
      return true;
    });

    $("history-total").textContent = state.points.toLocaleString("ja-JP");
    var earnSum = all.filter(function (h) { return h.delta > 0; }).reduce(function (a, h) { return a + h.delta; }, 0);
    var useSum = all.filter(function (h) { return h.delta < 0; }).reduce(function (a, h) { return a + h.delta; }, 0);
    $("history-earn").textContent = "+" + earnSum.toLocaleString("ja-JP") + "pt";
    $("history-use").textContent = useSum.toLocaleString("ja-JP") + "pt";

    var container = $("history-list");
    container.innerHTML = "";
    if (!filtered.length) {
      container.innerHTML = '<p class="history-empty">該当する履歴はありません</p>';
      return;
    }
    filtered.forEach(function (h) {
      var item = document.createElement("div");
      item.className = "history-item";

      var icon = document.createElement("div");
      icon.className = "history-icon " + (h.delta >= 0 ? "earn" : "use");
      icon.innerHTML = ICONS[h.delta >= 0 ? "plus" : "minus"];

      var body = document.createElement("div");
      body.className = "history-item-body";
      var title = document.createElement("p");
      title.className = "history-item-title";
      title.textContent = h.label;
      var meta = document.createElement("p");
      meta.className = "history-item-meta";
      meta.textContent = formatHistoryDate(h.time) + " ・ " + h.sub;
      body.appendChild(title);
      body.appendChild(meta);

      var amount = document.createElement("span");
      amount.className = "history-item-amount " + (h.delta >= 0 ? "earn" : "use");
      amount.textContent = (h.delta >= 0 ? "+" : "") + h.delta.toLocaleString("ja-JP") + "pt";

      item.appendChild(icon);
      item.appendChild(body);
      item.appendChild(amount);
      container.appendChild(item);
    });
  }

  function renderExpiry() {
    var list = $("expiry-list");
    list.innerHTML = "";
    var item = document.createElement("div");
    item.className = "expiry-item";
    var date = document.createElement("span");
    date.className = "expiry-date";
    date.textContent = EXPIRY_DATE + "まで";
    var amount = document.createElement("span");
    amount.className = "expiry-amount";
    amount.textContent = state.points.toLocaleString("ja-JP") + " pt";
    item.appendChild(date);
    item.appendChild(amount);
    list.appendChild(item);
  }

