  function resetQRSwipe() {
    var thumb = $("qr-swipe-thumb");
    thumb.style.left = "4px";
    thumb.dataset.x = "0";
  }

  function setupQRSwipe() {
    var thumb = $("qr-swipe-thumb");
    var track = $("qr-swipe-track");
    var dragging = false;
    var startClientX = 0;
    var startLeft = 4;

    function maxX() {
      return track.clientWidth - thumb.offsetWidth - 8;
    }

    thumb.addEventListener("pointerdown", function (e) {
      dragging = true;
      startClientX = e.clientX;
      startLeft = parseFloat(thumb.style.left) || 4;
      thumb.classList.add("dragging");
      thumb.setPointerCapture(e.pointerId);
    });

    thumb.addEventListener("pointermove", function (e) {
      if (!dragging) return;
      var delta = e.clientX - startClientX;
      var x = Math.max(0, Math.min(maxX(), startLeft - 4 + delta));
      thumb.style.left = (4 + x) + "px";
      thumb.dataset.x = String(x);
    });

    function endDrag() {
      if (!dragging) return;
      dragging = false;
      thumb.classList.remove("dragging");
      var x = parseFloat(thumb.dataset.x || "0");
      var m = maxX();
      if (m > 0 && x >= m * 0.8) {
        thumb.style.left = (4 + m) + "px";
        confirmQRPayment();
      } else {
        resetQRSwipe();
      }
    }

    thumb.addEventListener("pointerup", endDrag);
    thumb.addEventListener("pointercancel", endDrag);
  }

  function showToast(msg) {
    var toast = $("toast");
    $("toast-msg").textContent = msg;
    toast.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toast.classList.remove("show"); }, 2400);
  }

  function fireConfetti(x, y, colors, count) {
    if (reduceMotion) return;
    count = count || 70;
    var canvas = $("confetti-canvas");
    var ctx = canvas.getContext("2d");
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    var particles = [];
    for (var i = 0; i < count; i++) {
      var angle = Math.random() * Math.PI * 2;
      var speed = 3 + Math.random() * 7;
      particles.push({
        x: x, y: y,
        vx: Math.cos(angle) * speed * (0.4 + Math.random()),
        vy: Math.sin(angle) * speed - 5 - Math.random() * 4,
        size: 4 + Math.random() * 5,
        color: colors[Math.floor(Math.random() * colors.length)],
        rot: Math.random() * 360,
        vr: (Math.random() - 0.5) * 22,
        life: 0,
        maxLife: 55 + Math.random() * 35
      });
    }

    function tick() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      var alive = false;
      for (var i = 0; i < particles.length; i++) {
        var p = particles[i];
        if (p.life > p.maxLife) continue;
        alive = true;
        p.vy += 0.28;
        p.x += p.vx;
        p.y += p.vy;
        p.rot += p.vr;
        p.life++;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate((p.rot * Math.PI) / 180);
        ctx.globalAlpha = Math.max(0, 1 - p.life / p.maxLife);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6);
        ctx.restore();
      }
      if (alive) requestAnimationFrame(tick);
      else ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    tick();
  }

